import Adapter, { ModelLike } from './adapter.js'
import type {
  JsonApiDocument,
  JsonApiLink,
  JsonApiLinks,
  JsonApiRelationship,
  JsonApiRelationships,
  JsonApiResource,
  JsonApiResourceIdentifier,
  PresenterOptions,
  RelationshipConfig,
} from './types.js'
import { filterByFields } from './utils.js'

function buildLinks(link: JsonApiLink | string | null | undefined): JsonApiLink | undefined {
  if (link == null) {
    return
  }
  if (typeof link === 'object' && (link.self != null || link.related != null)) {
    return link
  } else {
    return { self: String(link) }
  }
}

// eslint-disable-next-line @typescript-eslint/explicit-function-return-type -- Return type is inferred from class
export default function createPresenter(adapter: typeof Adapter) {
  class Presenter {
    declare ['constructor']: typeof Presenter

    static adapter = adapter
    static type = 'objects'
    static fields?: string[]

    scope: JsonApiDocument

    constructor(scope?: JsonApiDocument) {
      this.scope = scope ?? { data: null }
    }

    id(instance: ModelLike): string | undefined {
      return this.constructor.adapter.id(instance)
    }

    selfLinks(_instance: ModelLike): JsonApiLink | string | undefined {
      return undefined
    }

    links(_instance?: ModelLike): JsonApiLinks | undefined {
      return undefined
    }

    relationships(): Record<string, typeof Presenter | RelationshipConfig<typeof Presenter>> {
      return {}
    }

    attributes(instance: ModelLike | null): Record<string, unknown> {
      if (instance == null) {
        return {}
      }
      const attributes = { ...this.constructor.adapter.get(instance) }
      delete attributes['id']

      const relationships = this.relationships()
      if (relationships) {
        for (const key in relationships) {
          delete attributes[key]
        }
      }

      return filterByFields(attributes, this.constructor.fields)
    }

    includeRelationships(scope: JsonApiDocument, instance: ModelLike): unknown[] {
      const relationships = this.relationships()
      const result: unknown[] = []
      if (!relationships) {
        return result
      }

      for (const key in relationships) {
        const entry = relationships[key]
        if (!entry) throw new Error(`Presenter for ${key} in ${this.constructor.type} is not defined`)
        const factory = typeof entry === 'function' ? entry : entry.presenter

        const presenter = new factory(scope)

        // eslint-disable-next-line @typescript-eslint/consistent-type-assertions -- unknown from adapter.get
        const data = this.constructor.adapter.get(instance, key) as ModelLike | ModelLike[] | null
        result.push(presenter.toJSON(data, { include: true }))
      }
      return result
    }

    buildRelationships(instance: ModelLike | null, options: { payload?: boolean } = {}): JsonApiRelationships | null {
      if (instance == null) {
        return null
      }
      const rels = this.relationships()
      const links = this.links(instance) || {}
      const isPayload = options.payload === true
      let relationships: JsonApiRelationships | null = null

      if (!rels) {
        return null
      }

      for (const key in rels) {
        const entry = rels[key]
        if (!entry) continue

        const isConfig = typeof entry !== 'function'
        const presenter = isConfig ? entry.presenter : entry
        const hasMany = isConfig ? entry.hasMany : undefined
        const optional = isConfig ? (entry.optional ?? false) : false

        const linkValue = links[key]
        const hasLinks = linkValue != null

        // eslint-disable-next-line @typescript-eslint/consistent-type-assertions -- unknown from adapter.get
        const data = this.constructor.adapter.get(instance, key) as ModelLike | ModelLike[] | null | undefined
        const keyPresent = this.constructor.adapter.has(instance, key)

        const buildData = (d: ModelLike): JsonApiResourceIdentifier => {
          const id = this.constructor.adapter.id(d)
          if (!id) {
            throw new Error(
              `Model of type ${presenter.type} is missing an id (relationship '${key}' of ${this.constructor.type})`,
            )
          }
          return { id, type: presenter.type }
        }

        // Skip in payload mode: an omitted relationship in a write must not be
        // confused with the model simply not having loaded it.
        if (optional && !keyPresent && !isPayload) {
          if (hasLinks) {
            if (!relationships) relationships = {}
            relationships[key] = { links: buildLinks(linkValue) }
          }
          continue
        }

        if (!relationships) relationships = {}
        const rel: JsonApiRelationship = {}

        if (Array.isArray(data)) {
          rel.data = data.map(buildData)
        } else if (data != null) {
          rel.data = buildData(data)
        } else if (hasMany === true) {
          rel.data = []
        } else if (!hasLinks) {
          rel.data = null
        }

        if (hasLinks) {
          rel.links = buildLinks(linkValue)
        }

        relationships[key] = rel
      }
      return relationships
    }

    buildSelfLink(instance: ModelLike): JsonApiLink | undefined {
      return buildLinks(this.selfLinks(instance))
    }

    toJSON(
      instanceOrCollection: ModelLike | ModelLike[] | null | undefined,
      options?: PresenterOptions,
    ): JsonApiDocument {
      const opts = options ?? {}
      if (opts.meta != null) {
        this.scope.meta = opts.meta
      }
      if (opts.links != null) {
        this.scope.links = opts.links
      }
      if (!this.scope.data) {
        this.scope.data = null
      }

      if (instanceOrCollection == null) {
        return this.scope
      }

      if (Array.isArray(instanceOrCollection)) {
        const collection = instanceOrCollection
        if (!this.scope.data) {
          this.scope.data = []
        }
        collection.forEach((instance: ModelLike) => {
          return this.toJSON(instance, options)
        })
      } else {
        const instance = instanceOrCollection
        let added = true
        const model: JsonApiResource = {
          id: this.id(instance),
          type: this.constructor.type,
          attributes: this.attributes(instance),
        }
        if (model.id === undefined) {
          delete model.id
        }
        const relationships = this.buildRelationships(instance)
        if (relationships != null) {
          model.relationships = relationships
        }
        const links = this.buildSelfLink(instance)
        if (links != null) {
          model.links = links
        }

        if (opts.include) {
          if (!this.scope.included) {
            this.scope.included = []
          }
          const allResources = (this.scope.included || []).concat(
            Array.isArray(this.scope.data) ? this.scope.data : this.scope.data ? [this.scope.data] : [],
          )
          if (!allResources.some((i) => i.id === model.id && i.type === model.type)) {
            this.scope.included.push(model)
          } else {
            added = false
          }
        } else if (this.scope.data != null) {
          if (Array.isArray(this.scope.data)) {
            if (!this.scope.data.some((i) => i.id === model.id && i.type === model.type)) {
              this.scope.data.push(model)
            } else {
              added = false
            }
          } else {
            // data is a single object, convert to array if needed
            this.scope.data = model
          }
        } else {
          this.scope.data = model
        }

        if (added) {
          this.includeRelationships(this.scope, instance)
        }
      }
      return this.scope
    }

    payload(instance: ModelLike, options?: PresenterOptions): JsonApiDocument {
      if (Array.isArray(instance)) {
        throw new Error('payload() expects a single resource, not an array')
      }
      if (instance == null) {
        throw new Error('payload() requires a resource, got null')
      }
      const model: JsonApiResource = {
        type: this.constructor.type,
        attributes: this.attributes(instance),
      }
      const id = this.id(instance)
      if (id != null) {
        model.id = id
      }
      const relationships = this.buildRelationships(instance, { payload: true })
      if (relationships != null) {
        model.relationships = relationships
      }
      const result: JsonApiDocument = { data: model }
      const opts = options ?? {}
      if (opts.meta != null) result.meta = opts.meta
      if (opts.links != null) result.links = opts.links
      return result
    }

    render(instanceOrCollection: ModelLike | ModelLike[] | null, options?: PresenterOptions): JsonApiDocument {
      return this.toJSON(instanceOrCollection, options)
    }

    static toJSON(instanceOrCollection: ModelLike | ModelLike[] | null, options?: PresenterOptions): JsonApiDocument {
      return new this().toJSON(instanceOrCollection, options)
    }

    static render(instanceOrCollection: ModelLike | ModelLike[] | null, options?: PresenterOptions): JsonApiDocument {
      return new this().render(instanceOrCollection, options)
    }

    static payload(instance: ModelLike, options?: PresenterOptions): JsonApiDocument {
      return new this().payload(instance, options)
    }
  }

  return Presenter
}

export type Presenter = ReturnType<typeof createPresenter>
